import { cookies, headers } from 'next/headers'

const DEFAULT_THEME = 'light'
const DEFAULT_LANGUAGE = 'en'

/**
 * Picks the highest-priority language out of an `Accept-Language` header value,
 * e.g. `fr-CH, fr;q=0.9, en;q=0.8, *;q=0.5` -> `fr-CH`.
 *
 * Tags are ranked by their `q` value (defaulting to 1 when omitted) rather than
 * by document order, since clients are not required to send them pre-sorted.
 */
function parsePreferredLanguage(acceptLanguage: string | null): string {
  if (!acceptLanguage) return DEFAULT_LANGUAGE

  const preferred = acceptLanguage
    .split(',')
    .map((part) => {
      const [tag, ...params] = part.trim().split(';')
      const qParam = params.find((param) => param.trim().startsWith('q='))
      const quality = qParam ? Number.parseFloat(qParam.trim().slice(2)) : 1

      return {
        tag: tag.trim(),
        quality: Number.isNaN(quality) ? 0 : quality,
      }
    })
    // Drop the wildcard and any tag explicitly rejected with `q=0`.
    .filter((entry) => entry.tag !== '' && entry.tag !== '*' && entry.quality > 0)
    .sort((a, b) => b.quality - a.quality)[0]

  return preferred?.tag ?? DEFAULT_LANGUAGE
}

export default async function Preferences() {
  const [cookieStore, headersList] = await Promise.all([cookies(), headers()])

  const theme = cookieStore.get('theme')?.value || DEFAULT_THEME
  const language = parsePreferredLanguage(headersList.get('accept-language'))

  return (
    <dl>
      <dt>Theme</dt>
      <dd>{theme}</dd>

      <dt>Preferred language</dt>
      <dd>{language}</dd>
    </dl>
  )
}

